def simplify_path(path: str) -> str:
    # Split the path by '/' and filter out empty strings and '.'
    parts = [part for part in path.split('/') if part and part != '.']

    # Process the parts to handle '..'
    stack = []
    for part in parts:
        if part == '..':
            # Pop from stack if not empty (can't go above root)
            if stack:
                stack.pop()
        else:
            # Regular directory name
            stack.append(part)

    # Join the parts back with '/' and ensure it starts with '/'
    return '/' + '/'.join(stack)
